result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/apgar.py", "content": """"APGAR score calculator — educational neonatal-simulation use only.

Five components (Appearance, Pulse, Grimace, Activity, Respiration),
each scored 0, 1, or 2. Total ranges 0-10.
"""

REQUIRED_KEYS = ("appearance", "pulse", "grimace", "activity", "respiration")
VALID_VALUES = {0, 1, 2}


def apgar(scores: dict) -> int:
    """Validate component scores and return the APGAR total (0-10)."""
    if not isinstance(scores, dict):
        raise TypeError("scores must be a dict")
    keys = set(scores)
    expected = set(REQUIRED_KEYS)
    missing = sorted(expected - keys)
    extra = sorted(keys - expected)
    if missing:
        raise KeyError(f"missing required component(s): {missing}")
    if extra:
        raise KeyError(f"unrecognized component(s): {extra}")
    for key in REQUIRED_KEYS:
        value = scores[key]
        if value not in VALID_VALUES:
            raise ValueError(f"{key!r} must be one of {sorted(VALID_VALUES)}, got {value!r}")
    return sum(scores[key] for key in REQUIRED_KEYS)


def interpret(total: int) -> str:
    """Classify an APGAR total."""
    if not 0 <= total <= 10:
        raise ValueError(f"total must be within 0-10, got {total!r}")
    if total >= 7:
        return "reassuring"
    if total >= 4:
        return "moderately abnormal"
    return "low"


def trend(one_min: int, five_min: int) -> str:
    """Compare 1-minute and 5-minute totals: 'improving', 'stable', or 'worsening'."""
    for total in (one_min, five_min):
        if not 0 <= total <= 10:
            raise ValueError(f"totals must be within 0-10, got {total!r}")
    if five_min > one_min:
        return "improving"
    if five_min < one_min:
        return "worsening"
    return "stable"
